const cfg=__CFG__;
let result={}; try { result=pm.response.json(); } catch (_) {}
const root=pm.variables.get('qaRoot');
const ids=JSON.parse(pm.variables.get('qaOwnedIds')||'[]');
// Thu hồi cả bản ghi tạo thành công ngoài dự kiến để ca lỗi không để rác.
if(cfg.method==='POST' && pm.response.code===201 && result.data?.fullName?.startsWith('QA_AUT_')) ids.push(result.data._id);
for(const id of [...new Set(ids)]) {
  const alreadyDeleted=cfg.method==='DELETE' && pm.response.code===200 && id===pm.variables.get('qaAuthorId');
  if(!alreadyDeleted) pm.sendRequest({url:root+'/author/'+id,method:'DELETE'},(err,res)=>{
    pm.test(cfg.id+' cleanup '+id,()=>{pm.expect(err).to.equal(null);pm.expect(res.code).to.equal(200);});
  });
}
pm.test(cfg.id+' HTTP',()=>pm.expect(pm.response.code).to.equal(cfg.code));
pm.test(cfg.id+' wrapper',()=>{
  pm.expect(result.status).to.equal(cfg.code<400?'success':'error');
  pm.expect(result).to.have.property('data');
});
if(cfg.message) pm.test(cfg.id+' message',()=>pm.expect(result.message).to.equal(cfg.message));
if(cfg.field) pm.test(cfg.id+' lỗi từng trường',()=>{
  pm.expect(result.errors).to.be.an('array');
  pm.expect(result.errors.some(e=>e.field===cfg.field && typeof e.message==='string')).to.equal(true);
});
if(cfg.code<400) pm.test(cfg.id+' dữ liệu',()=>{
  if(cfg.method==='GET_LIST') {pm.expect(result.data).to.be.an('array');return;}
  pm.expect(result.data._id).to.match(/^[a-f0-9]{24}$/);
  if(cfg.method!=='POST') pm.expect(result.data._id).to.equal(pm.variables.get('qaAuthorId'));
  if(cfg.body && ['POST','PUT'].includes(cfg.method)) {
    const expected=JSON.parse(pm.variables.replaceIn(JSON.stringify(cfg.body)));
    pm.expect(result.data.fullName).to.equal(expected.fullName);
    if(expected.affiliation!==undefined) pm.expect(result.data.affiliation).to.equal(expected.affiliation);
  }
});

if(cfg.code>=400) pm.test(cfg.id+' data null',()=>pm.expect(result.data).to.equal(null));
if(cfg.fieldMessage) pm.test(cfg.id+' field message',()=>pm.expect(result.errors.some(e=>e.field===cfg.field && e.message===cfg.fieldMessage)).to.equal(true));

if(cfg.code<400 && cfg.body?.notes!==undefined) pm.test(cfg.id+' notes',()=>pm.expect(result.data.notes).to.equal(cfg.body.notes));
if(cfg.id.endsWith('UNKNOWN_STRIPPED')) pm.test(cfg.id+' extra stripped',()=>pm.expect(result.data).not.to.have.property('extra'));
